package com.portfolio.shopsphere.model; import jakarta.persistence.*;import java.time.Instant; @Entity @Table(name="orders") public class Order{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;String customerEmail;double total;String status="PLACED";Instant createdAt=Instant.now();public Long getId(){return id;}public String getCustomerEmail(){return customerEmail;}public void setCustomerEmail(String v){customerEmail=v;}public double getTotal(){return total;}public void setTotal(double v){total=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Instant getCreatedAt(){return createdAt;}}
